{
  "root_cause": "The modal fails to open because the initialization function has multiple bugs: generateTriggerMap uses an array instead of an object, init uses undefined variables (triggerAttr, targetModal), and getFocusableNodes passes an array to querySelectorAll causing a TypeError. Additionally, the Space key event propagates and closes the modal when pressing Space on a checkbox.",
  "repair_strategy": "Fix generateTriggerMap to return an object, fix init to properly create Modal instances for each modal and register triggers without showing, fix getFocusableNodes to join selectors into a string, fix setFocusToFirstNode to use if-else for clarity, and add a Space key handler in onKeydown to stop propagation.",
  "edits": [
    {
      "path": "lib/src/index.js",
      "sha256": "0db2038c36c8c8c4730018c0ea419249e45923efa8315729f12b4d8da0d5fa2c",
      "before": "  const generateTriggerMap = (triggers, triggerAttr) => {
    const triggerMap = []

    triggers.forEach(trigger => {
      const targetModal = trigger.attributes[triggerAttr].value
      if (triggerMap[targetModal] === undefined) triggerMap[targetModal] = []
      triggerMap[targetModal].push(trigger)
    })

    return triggerMap
  }",
      "after": "  const generateTriggerMap = (triggers, triggerAttr) => {
    const triggerMap = {}

    triggers.forEach(trigger => {
      const targetModal = trigger.attributes[triggerAttr].value
      if (triggerMap[targetModal] === undefined) triggerMap[targetModal] = []
      triggerMap[targetModal].push(trigger)
    })

    return triggerMap
  }"
    },
    {
      "path": "lib/src/index.js",
      "sha256": "0db2038c36c8c8c4730018c0ea419249e45923efa8315729f12b4d8da0d5fa2c",
      "before": "  const init = config => {
    // Create an config object with default openTrigger
    const options = Object.assign({}, { openTrigger: 'data-micromodal-trigger' }, config)

    // Collects all the nodes with the trigger
    const triggers = [...document.querySelectorAll(`[${ options.openTrigger }]`)]

    // Makes a mappings of modals with their triggers
    const triggerMap = generateTriggerMap(triggers, triggerAttr)

    // Checks if modals and triggers exist in dom
    if (options.debugMode === true && validateModalPresence(targetModal) === false) return

    // clear events in case previous modal wasn't close
    if (activeModal) activeModal.removeEventListeners()

    // stores reference to active modal
    activeModal = new Modal(options) // eslint-disable-line no-new
    activeModal.showModal()
  }",
      "after": "  const init = config => {
    const options = Object.assign({}, { openTrigger: 'data-micromodal-trigger' }, config)
    const triggers = [...document.querySelectorAll(`[${options.openTrigger}]`)]
    const triggerMap = generateTriggerMap(triggers, options.openTrigger)
    if (options.debugMode === true) {
      for (const targetModal in triggerMap) {
        if (!validateModalPresence(targetModal)) return
      }
    }
    if (activeModal) activeModal.removeEventListeners()
    for (const targetModal in triggerMap) {
      const triggersForModal = triggerMap[targetModal]
      const modalOptions = Object.assign({}, options, { targetModal, triggers: triggersForModal })
      new Modal(modalOptions) // eslint-disable-line no-new
    }
  }"
    },
    {
      "path": "lib/src/index.js",
      "sha256": "0db2038c36c8c8c4730018c0ea419249e45923efa8315729f12b4d8da0d5fa2c",
      "before": "    getFocusableNodes () {
      const nodes = this.modal.querySelectorAll(FOCUSABLE_ELEMENTS)
      return Array(...nodes)
    }",
      "after": "    getFocusableNodes () {
      const selector = FOCUSABLE_ELEMENTS.join(',')
      const nodes = this.modal.querySelectorAll(selector)
      return Array.from(nodes)
    }"
    },
    {
      "path": "lib/src/index.js",
      "sha256": "0db2038c36c8c8c4730018c0ea419249e45923efa8315729f12b4d8da0d5fa2c",
      "before": "    setFocusToFirstNode () {
      if (this.config.disableFocus) return

      const focusableNodes = this.getFocusableNodes()

      // no focusable nodes
      if (focusableNodes.length === 0) return

      // remove nodes on whose click, the modal closes
      // could not think of a better name :(
      const nodesWhichAreNotCloseTargets = focusableNodes.filter(node => {
        return !node.hasAttribute(this.config.closeTrigger)
      })

      if (nodesWhichAreNotCloseTargets.length > 0) nodesWhichAreNotCloseTargets[0].focus()
      if (nodesWhichAreNotCloseTargets.length === 0) focusableNodes[0].focus()
    }",
      "after": "    setFocusToFirstNode () {
      if (this.config.disableFocus) return

      const focusableNodes = this.getFocusableNodes()

      // no focusable nodes
      if (focusableNodes.length === 0) return

      // remove nodes on whose click, the modal closes
      // could not think of a better name :(
      const nodesWhichAreNotCloseTargets = focusableNodes.filter(node => {
        return !node.hasAttribute(this.config.closeTrigger)
      })

      if (nodesWhichAreNotCloseTargets.length > 0) {
        nodesWhichAreNotCloseTargets[0].focus()
      } else if (nodesWhichAreNotCloseTargets.length === 0) {
        focusableNodes[0].focus()
      }
    }"
    },
    {
      "path": "lib/src/index.js",
      "sha256": "0db2038c36c8c8c4730018c0ea419249e45923efa8315729f12b4d8da0d5fa2c",
      "before": "    onKeydown (event) {
      if (event.keyCode === 27) this.closeModal(event) // esc
      if (event.keyCode === 9) this.retainFocus(event) // tab
    }",
      "after": "    onKeydown (event) {
      if (event.keyCode === 27) this.closeModal(event) // esc
      if (event.keyCode === 9) this.retainFocus(event) // tab
      if (event.keyCode === 32) event.stopPropagation() // space
    }"
    }
  ],
  "expected_accessibility_effect": "Pressing Enter on the trigger opens the modal, focus moves to the first checkbox, pressing Space toggles the checkbox without closing the modal, and the modal stays open (aria-hidden remains false).",
  "functional_risks": [
    "Changes to init may affect multiple modal handling if more modals are added.",
    "The Space key stopPropagation may interfere with custom Space-based shortcuts that rely on event propagation within the modal.",
    "If other components depend on Space key bubbling from inner elements, they will no longer receive the event."
  ],
  "verification_requirements": [
    "Verify that pressing Enter on the trigger opens the modal (aria-hidden becomes false).",
    "Verify that focus moves to the weekly checkbox after opening.",
    "Verify that pressing Space on the weekly checkbox toggles it and the modal stays open.",
    "Verify that pressing Escape closes the modal and restores focus to the trigger.",
    "Verify that Tab key trapping works within the modal."
  ]
}
